mapper.select:
select uc.id, uc.coupon_type_id, ct.name as type_name, ct.min_spend, ct.discount_amount, ct.discount_rate, ct.valid_days, uc.start_time, uc.end_time, uc.status from user_coupon uc join coupon_type ct on uc.coupon_type_id = ct.id
uc.user_id = #{userId} and uc.status = #{status}
order by uc.id desc
